trazabilidad_archivos.codigo_final:
*, *::before, *::after {
  box-sizing: border-box;
}

body, h1, h2, h3, h4, h5, h6, p, ul, ol, figure, blockquote {
  margin: 0;
  padding: 0;
}

ul, ol {
  list-style: none;
}

img {
  display: block;
  max-width: 100%;
}

a {
  text-decoration: none;
  color: inherit;
}

button {
  cursor: pointer;
  border: none;
  background: none;
}

:root {
  --color-primary: #0A0A0A;
  --color-secondary: #1C1C1E;
  --color-accent: #C9A84C;
  --color-accent-hover: #B8973D;
  --color-text-primary: #F5F5F5;
  --color-text-secondary: #A0A0A0;
  --color-text-muted: #606060;
  --color-border: #2C2C2E;
  --color-surface: #141414;
  --color-error: #E05252;
  --color-success: #4CAF82;

  --font-display: 'Playfair Display', Georgia, serif;
  --font-body: 'Inter', system-ui, sans-serif;
  --font-size-base: 1rem;
  --font-size-sm: 0.875rem;
  --font-size-lg: 1.125rem;
  --font-size-xl: 1.5rem;
  --font-size-2xl: 2rem;
  --font-size-3xl: 2.75rem;
  --font-size-4xl: 3.75rem;
  --line-height-tight: 1.2;
  --line-height-normal: 1.6;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-bold: 700;

  --space-1: 0.5rem;
  --space-2: 1rem;
  --space-3: 1.5rem;
  --space-4: 2rem;
  --space-6: 3rem;
  --space-8: 4rem;
  --space-12: 6rem;
  --space-16: 8rem;

  --container-max: 1200px;
  --container-padding: var(--space-4);
  --border-radius-sm: 4px;
  --border-radius-md: 8px;
  --border-radius-lg: 16px;
  --transition-fast: 150ms ease;
  --transition-base: 250ms ease;
  --transition-slow: 400ms ease;
}

html {
  font-size: 100%;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-body);
  font-size: var(--font-size-base);
  font-weight: var(--font-weight-regular);
  line-height: var(--line-height-normal);
  color: var(--color-text-primary);
  background-color: var(--color-primary);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-display);
  font-weight: var(--font-weight-bold);
  line-height: var(--line-height-tight);
  color: var(--color-text-primary);
}

h1 { font-size: var(--font-size-4xl); }
h2 { font-size: var(--font-size-3xl); }
h3 { font-size: var(--font-size-2xl); }
h4 { font-size: var(--font-size-xl); }
h5 { font-size: var(--font-size-lg); }
h6 { font-size: var(--font-size-base); }

p {
  font-size: var(--font-size-base);
  line-height: var(--line-height-normal);
  color: var(--color-text-secondary);
}

.container {
  width: 100%;
  max-width: var(--container-max);
  margin-inline: auto;
  padding-inline: var(--container-padding);
}

.section {
  padding-block: var(--space-12);
}

.section--alt {
  background-color: var(--color-secondary);
}

.section__header {
  text-align: center;
  margin-bottom: var(--space-8);
}

.section__eyebrow {
  display: block;
  font-family: var(--font-body);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: var(--space-2);
}

.section__title {
  font-size: var(--font-size-3xl);
  color: var(--color-text-primary);
  margin-bottom: var(--space-2);
}

.section__subtitle {
  font-size: var(--font-size-lg);
  color: var(--color-text-secondary);
  max-width: 600px;
  margin-inline: auto;
}

/* ─── HEADER / NAV ─── */

.site-header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background-color: var(--color-primary);
  border-bottom: 1px solid var(--color-border);
  height: 72px;
  display: flex;
  align-items: center;
}

.site-header .container {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.nav__logo {
  font-family: var(--font-display);
  font-size: var(--font-size-xl);
  font-weight: var(--font-weight-bold);
  color: var(--color-text-primary);
  letter-spacing: 0.02em;
}

.nav__logo span {
  color: var(--color-accent);
}

.nav__list {
  display: flex;
  align-items: center;
  gap: var(--space-6);
}

.nav__link {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-text-secondary);
  transition: color var(--transition-fast);
}

.nav__link:hover,
.nav__link--active {
  color: var(--color-accent);
}

.nav__cta {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-primary);
  background-color: var(--color-accent);
  padding: var(--space-1) var(--space-3);
  border-radius: var(--border-radius-sm);
  transition: background-color var(--transition-fast);
}

.nav__cta:hover {
  background-color: var(--color-accent-hover);
}

.nav__toggle {
  display: none;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
  width: 28px;
  height: 28px;
  cursor: pointer;
  background: none;
  border: none;
  padding: 0;
}

.nav__toggle-bar {
  display: block;
  width: 100%;
  height: 2px;
  background-color: var(--color-text-primary);
  border-radius: 2px;
  transition: transform var(--transition-base), opacity var(--transition-base);
}

@media (max-width: 768px) {
  .nav__toggle {
    display: flex;
  }

  .nav__menu {
    display: none;
    position: absolute;
    top: 72px;
    left: 0;
    right: 0;
    background-color: var(--color-primary);
    border-bottom: 1px solid var(--color-border);
    padding: var(--space-4);
  }

  .nav__menu--open {
    display: block;
  }

  .nav__list {
    flex-direction: column;
    align-items: flex-start;
    gap: var(--space-3);
  }

  .nav__cta {
    margin-top: var(--space-2);
    display: inline-block;
  }
}

/* ─── HERO ─── */

.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  padding-top: 72px;
  background-color: var(--color-primary);
  position: relative;
  overflow: hidden;
}

.hero__content {
  max-width: 720px;
}

.hero__eyebrow {
  display: block;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: var(--space-3);
}

.hero__title {
  font-size: var(--font-size-4xl);
  line-height: var(--line-height-tight);
  color: var(--color-text-primary);
  margin-bottom: var(--space-4);
}

.hero__title em {
  font-style: italic;
  color: var(--color-accent);
}

.hero__description {
  font-size: var(--font-size-lg);
  color: var(--color-text-secondary);
  line-height: var(--line-height-normal);
  margin-bottom: var(--space-6);
  max-width: 560px;
}

.hero__actions {
  display: flex;
  align-items: center;
  gap: var(--space-3);
  flex-wrap: wrap;
}

.hero__image {
  position: absolute;
  right: 0;
  top: 72px;
  bottom: 0;
  width: 45%;
  object-fit: cover;
  opacity: 0.35;
}

@media (max-width: 768px) {
  .hero__title {
    font-size: var(--font-size-3xl);
  }

  .hero__image {
    display: none;
  }

  .hero__content {
    max-width: 100%;
  }
}

/* ─── BUTTONS ─── */

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-1);
  font-family: var(--font-body);
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  border-radius: var(--border-radius-sm);
  padding: var(--space-2) var(--space-4);
  transition: background-color var(--transition-fast), color var(--transition-fast), border-color var(--transition-fast);
  cursor: pointer;
  border: 1px solid transparent;
}

.btn--primary {
  background-color: var(--color-accent);
  color: var(--color-primary);
  border-color: var(--color-accent);
}

.btn--primary:hover {
  background-color: var(--color-accent-hover);
  border-color: var(--color-accent-hover);
}

.btn--outline {
  background-color: transparent;
  color: var(--color-text-primary);
  border-color: var(--color-border);
}

.btn--outline:hover {
  border-color: var(--color-accent);
  color: var(--color-accent);
}

.btn--ghost {
  background-color: transparent;
  color: var(--color-accent);
  border-color: transparent;
  padding-inline: 0;
}

.btn--ghost:hover {
  color: var(--color-accent-hover);
}

/* ─── CARDS ─── */

.card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-md);
  overflow: hidden;
  transition: border-color var(--transition-base), transform var(--transition-base);
}

.card:hover {
  border-color: var(--color-accent);
  transform: translateY(-4px);
}

.card__image {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
}

.card__body {
  padding: var(--space-4);
}

.card__tag {
  display: inline-block;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--color-accent);
  margin-bottom: var(--space-2);
}

.card__title {
  font-size: var(--font-size-xl);
  color: var(--color-text-primary);
  margin-bottom: var(--space-2);
}

.card__excerpt {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  line-height: var(--line-height-normal);
  margin-bottom: var(--space-3);
}

.card__meta {
  font-size: var(--font-size-sm);
  color: var(--color-text-muted);
}

/* ─── GRID LAYOUTS ─── */

.grid--3col {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

@media (max-width: 1024px) {
  .grid--3col {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .grid--3col {
    grid-template-columns: 1fr;
  }
}

.grid--2col {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-6);
  align-items: center;
}

@media (max-width: 768px) {
  .grid--2col {
    grid-template-columns: 1fr;
  }
}

.grid--4col {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: var(--space-4);
}

@media (max-width: 1024px) {
  .grid--4col {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .grid--4col {
    grid-template-columns: 1fr;
  }
}

/* ─── STAT / COUNTER ─── */

.stat {
  text-align: center;
  padding: var(--space-4);
}

.stat__number {
  font-family: var(--font-display);
  font-size: var(--font-size-4xl);
  font-weight: var(--font-weight-bold);
  color: var(--color-accent);
  line-height: var(--line-height-tight);
}

.stat__label {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  margin-top: var(--space-1);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

/* ─── TESTIMONIAL ─── */

.testimonial {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-md);
  padding: var(--space-6);
  position: relative;
}

.testimonial__quote {
  font-size: var(--font-size-lg);
  color: var(--color-text-primary);
  line-height: var(--line-height-normal);
  font-style: italic;
  margin-bottom: var(--space-4);
}

.testimonial__author {
  display: flex;
  align-items: center;
  gap: var(--space-2);
}

.testimonial__avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid var(--color-accent);
}

.testimonial__name {
  font-size: var(--font-size-base);
  font-weight: var(--font-weight-medium);
  color: var(--color-text-primary);
}

.testimonial__role {
  font-size: var(--font-size-sm);
  color: var(--color-text-muted);
}

.testimonial__accent {
  position: absolute;
  top: var(--space-4);
  right: var(--space-4);
  font-size: var(--font-size-3xl);
  color: var(--color-accent);
  opacity: 0.3;
  font-family: var(--font-display);
  line-height: 1;
}

/* ─── FORM ─── */

.form {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.form__group {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.form__row {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-3);
}

@media (max-width: 600px) {
  .form__row {
    grid-template-columns: 1fr;
  }
}

.form__label {
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  color: var(--color-text-secondary);
  letter-spacing: 0.04em;
}

.form__input,
.form__textarea,
.form__select {
  font-family: var(--font-body);
  font-size: var(--font-size-base);
  color: var(--color-text-primary);
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-sm);
  padding: var(--space-2) var(--space-3);
  width: 100%;
  transition: border-color var(--transition-fast);
  outline: none;
}

.form__input::placeholder,
.form__textarea::placeholder {
  color: var(--color-text-muted);
}

.form__input:focus,
.form__textarea:focus,
.form__select:focus {
  border-color: var(--color-accent);
}

.form__input--error,
.form__textarea--error {
  border-color: var(--color-error);
}

.form__textarea {
  resize: vertical;
  min-height: 140px;
}

.form__select {
  appearance: none;
  cursor: pointer;
}

.form__error {
  font-size: var(--font-size-sm);
  color: var(--color-error);
}

.form__success {
  font-size: var(--font-size-base);
  color: var(--color-success);
  text-align: center;
  padding: var(--space-3);
  border: 1px solid var(--color-success);
  border-radius: var(--border-radius-sm);
}

/* ─── DIVIDER ─── */

.divider {
  width: 60px;
  height: 2px;
  background-color: var(--color-accent);
  margin-block: var(--space-3);
}

.divider--center {
  margin-inline: auto;
}

/* ─── BADGE ─── */

.badge {
  display: inline-block;
  font-size: var(--font-size-sm);
  font-weight: var(--font-weight-medium);
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--color-accent);
  border: 1px solid var(--color-accent);
  border-radius: var(--border-radius-sm);
  padding: 0.2em 0.6em;
}

/* ─── PAGE HERO (inner pages) ─── */

.page-hero {
  padding-top: calc(72px + var(--space-12));
  padding-bottom: var(--space-12);
  background-color: var(--color-secondary);
  border-bottom: 1px solid var(--color-border);
  text-align: center;
}

.page-hero__title {
  font-size: var(--font-size-3xl);
  color: var(--color-text-primary);
  margin-bottom: var(--space-2);
}

.page-hero__subtitle {
  font-size: var(--font-size-lg);
  color: var(--color-text-secondary);
  max-width: 560px;
  margin-inline: auto;
}

@media (max-width: 768px) {
  .page-hero__title {
    font-size: var(--font-size-2xl);
  }
}

/* ─── ABOUT PAGE ─── */

.about-intro__image {
  width: 100%;
  aspect-ratio: 4 / 5;
  object-fit: cover;
  border-radius: var(--border-radius-lg);
  border: 1px solid var(--color-border);
}

.about-intro__content {
  display: flex;
  flex-direction: column;
  gap: var(--space-4);
  justify-content: center;
}

.about-intro__text {
  font-size: var(--font-size-lg);
  color: var(--color-text-secondary);
  line-height: var(--line-height-normal);
}

.values-list {
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
}

.value-item {
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  padding: var(--space-3);
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-md);
  transition: border-color var(--transition-base);
}

.value-item:hover {
  border-color: var(--color-accent);
}

.value-item__icon {
  font-size: var(--font-size-xl);
  color: var(--color-accent);
  flex-shrink: 0;
  line-height: 1;
}

.value-item__title {
  font-size: var(--font-size-base);
  font-weight: var(--font-weight-bold);
  color: var(--color-text-primary);
  margin-bottom: var(--space-1);
  font-family: var(--font-body);
}

.value-item__text {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  line-height: var(--line-height-normal);
}

.team-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

@media (max-width: 1024px) {
  .team-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .team-grid {
    grid-template-columns: 1fr;
  }
}

.team-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-md);
  overflow: hidden;
  text-align: center;
  transition: border-color var(--transition-base), transform var(--transition-base);
}

.team-card:hover {
  border-color: var(--color-accent);
  transform: translateY(-4px);
}

.team-card__image {
  width: 100%;
  aspect-ratio: 1 / 1;
  object-fit: cover;
}

.team-card__body {
  padding: var(--space-3);
}

.team-card__name {
  font-size: var(--font-size-lg);
  color: var(--color-text-primary);
  margin-bottom: var(--space-1);
}

.team-card__role {
  font-size: var(--font-size-sm);
  color: var(--color-accent);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

/* ─── SERVICES PAGE ─── */

.service-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-md);
  padding: var(--space-6);
  display: flex;
  flex-direction: column;
  gap: var(--space-3);
  transition: border-color var(--transition-base), transform var(--transition-base);
}

.service-card:hover {
  border-color: var(--color-accent);
  transform: translateY(-4px);
}

.service-card__icon {
  font-size: var(--font-size-3xl);
  color: var(--color-accent);
  line-height: 1;
}

.service-card__title {
  font-size: var(--font-size-xl);
  color: var(--color-text-primary);
}

.service-card__description {
  font-size: var(--font-size-base);
  color: var(--color-text-secondary);
  line-height: var(--line-height-normal);
  flex: 1;
}

.service-card__list {
  display: flex;
  flex-direction: column;
  gap: var(--space-1);
}

.service-card__list-item {
  font-size: var(--font-size-sm);
  color: var(--color-text-secondary);
  padding-left: var(--space-3);
  position: relative;
}

.service-card__list-item::before {
  content: '';
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background-color: var(--color-accent);
}

/* ─── BLOG PAGE ─── */

.blog-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: var(--space-4);
}

@media (max-width: 1024px) {
  .blog-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 600px) {
  .blog-grid {
    grid-template-columns: 1fr;
  }
}

.blog-card {
  background-color: var(--color-surface);
  border: 1px solid var(--color-border);
  border-radius: var(--border-radius-md);
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: border-color var(--transition-base), transform var(--transition-base);
}

.blog-card:hover {
  border-color: var(--color-accent);
  transform: translateY(-4px);
}

.blog-card__image {
  width: 100%;
  aspect-ratio: 16 / 9;
  object-fit: cover;
}

.blog-card__body {
  padding: var(--space-4);
  display: flex;
